theorem MvPolynomial.rename_rightInverse.{u_1, u_2, u_4} {σ : Type u_1} {τ : Type u_2} {R : Type u_4}
  [CommSemiring R] {f : σ → τ} {g : τ → σ} (hf : Function.RightInverse f g) :
  Function.RightInverse ⇑(MvPolynomial.rename f) ⇑(MvPolynomial.rename g)

theorem MvPolynomial.coeff_rename_mapDomain.{u_1, u_2, u_4} {σ : Type u_1} {τ : Type u_2} {R : Type u_4}
  [CommSemiring R] (f : σ → τ) (hf : Function.Injective f) (φ : MvPolynomial σ R) (d : σ →₀ ℕ) :
  MvPolynomial.coeff (Finsupp.mapDomain f d) ((MvPolynomial.rename f) φ) = MvPolynomial.coeff d φ

theorem MvPolynomial.killCompl_C.{u_1, u_2, u_4} {σ : Type u_1} {τ : Type u_2} {R : Type u_4}
  [CommSemiring R] {f : σ → τ} (hf : Function.Injective f) (r : R) :
  (MvPolynomial.killCompl hf) (MvPolynomial.C r) = MvPolynomial.C r

theorem MvPolynomial.rename_injective.{u_1, u_2, u_4} {σ : Type u_1} {τ : Type u_2} {R : Type u_4}
  [CommSemiring R] (f : σ → τ) (hf : Function.Injective f) :
