  [CommSemiring R] [CommSemiring S] (p : MvPolynomial σ R) {f : R →+* S}
  (hf : Function.Injective ⇑f) : ((MvPolynomial.map f) p).degrees = p.degrees

theorem MvPolynomial.degrees_rename_of_injective.{u, u_1, u_2} {R : Type u} {σ : Type u_1} {τ : Type u_2}
  [CommSemiring R] {p : MvPolynomial σ R} {f : σ → τ} (h : Function.Injective f) :
  ((MvPolynomial.rename f) p).degrees = Multiset.map f p.degrees

theorem MvPolynomial.degreeOf_mul_X_self_pow_eq_add_of_ne_zero.{u, u_1} {R : Type u} {σ : Type u_1}
  [CommSemiring R] {p : MvPolynomial σ R} (i : σ) (k : ℕ) (h : p ≠ 0) :
  MvPolynomial.degreeOf i (p * MvPolynomial.X i ^ k) = MvPolynomial.degreeOf i p + k

theorem MvPolynomial.totalDegree_smul_le.{u, v, u_1} {R : Type u} {S : Type v} {σ : Type u_1}
  [CommSemiring R] [CommSemiring S] [DistribMulAction R S] (a : R) (f : MvPolynomial σ S) :
  (a • f).totalDegree ≤ f.totalDegree

theorem MvPolynomial.degreeOf_mul_X_of_ne.{u, u_1} {R : Type u} {σ : Type u_1} [CommSemiring R] {i j : σ}
  (f : MvPolynomial σ R) (h : i ≠ j) :
  MvPolynomial.degreeOf i (f * MvPolynomial.X j) = MvPolynomial.degreeOf i f

theorem MvPolynomial.degrees_rename.{u, u_1, u_2} {R : Type u} {σ : Type u_1} {τ : Type u_2}
  [CommSemiring R] (f : σ → τ) (φ : MvPolynomial σ R) :
  ((MvPolynomial.rename f) φ).degrees ⊆ Multiset.map f φ.degrees

theorem MvPolynomial.totalDegree_renameEquiv.{u, u_1, u_2} {R : Type u} {σ : Type u_1} {τ : Type u_2}
  [CommSemiring R] (f : σ ≃ τ) (p : MvPolynomial σ R) :
  ((MvPolynomial.renameEquiv R f) p).totalDegree = p.totalDegree

theorem MvPolynomial.totalDegree_rename_le.{u, u_1, u_2} {R : Type u} {σ : Type u_1} {τ : Type u_2}
  [CommSemiring R] (f : σ → τ) (p : MvPolynomial σ R) :
  ((MvPolynomial.rename f) p).totalDegree ≤ p.totalDegree

theorem MvPolynomial.degreeOf_mul_X_eq_degreeOf_add_one_iff.{u, u_1} {R : Type u} {σ : Type u_1}
