  MvPolynomial.degreeOf j (f * MvPolynomial.X j) = MvPolynomial.degreeOf j f + 1 ↔ f ≠ 0

theorem MvPolynomial.degreeOf_rename_of_injective.{u, u_1, u_2} {R : Type u} {σ : Type u_1} {τ : Type u_2}
  [CommSemiring R] {p : MvPolynomial σ R} {f : σ → τ} (h : Function.Injective f) (i : σ) :
