theorem MvPolynomial.totalDegree_add_eq_left_of_totalDegree_lt.{u, u_1} {R : Type u} {σ : Type u_1}
  [CommSemiring R] {p q : MvPolynomial σ R} (h : q.totalDegree < p.totalDegree) :
  (p + q).totalDegree = p.totalDegree

theorem MvPolynomial.degreeOf_lt_iff.{u, u_1} {R : Type u} {σ : Type u_1} [CommSemiring R] {n : σ}
  {f : MvPolynomial σ R} {d : ℕ} (h : 0 < d) :
  MvPolynomial.degreeOf n f < d ↔ ∀ m ∈ f.support, m n < d

theorem MvPolynomial.totalDegree_finsetSum_le.{u, u_1, u_3} {R : Type u} {σ : Type u_1} [CommSemiring R]
  {ι : Type u_3} {s : Finset ι} {f : ι → MvPolynomial σ R} {d : ℕ}
  (hf : ∀ i ∈ s, (f i).totalDegree ≤ d) : (s.sum f).totalDegree ≤ d

theorem MvPolynomial.exists_degree_lt.{u, u_1} {R : Type u} {σ : Type u_1} [CommSemiring R] [Fintype σ]
  (f : MvPolynomial σ R) (n : ℕ) (h : f.totalDegree < n * Fintype.card σ) {d : σ →₀ ℕ}
  (hd : d ∈ f.support) : ∃ i, d i < n

theorem MvPolynomial.totalDegree_add_eq_right_of_totalDegree_lt.{u, u_1} {R : Type u} {σ : Type u_1}
  [CommSemiring R] {p q : MvPolynomial σ R} (h : q.totalDegree < p.totalDegree) :
  (q + p).totalDegree = p.totalDegree

theorem MvPolynomial.vars_prod.{u, u_1, u_3} {R : Type u} {σ : Type u_1} [CommSemiring R] {ι : Type u_3}
  [DecidableEq σ] {s : Finset ι} (f : ι → MvPolynomial σ R) :
  (∏ i ∈ s, f i).vars ⊆ s.biUnion fun i => (f i).vars

theorem MvPolynomial.exists_rename_eq_of_vars_subset_range.{u, u_1, u_2} {R : Type u} {σ : Type u_1}
  {τ : Type u_2} [CommSemiring R] (p : MvPolynomial σ R) (f : τ → σ) (hfi : Function.Injective f)
